"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { CSSProperties } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { motionTokens } from "@/lib/motion-tokens";
import { BetField, GameFrame, HistoryChips, PlayButton, formatAmount, roundAmount, usePlayMoney } from "./play-money";
import type { HistoryEntry } from "./play-money";
import styles from "./slide-game.module.css";

export interface SlideTile {
  /** Multiplier paid when the strip stops on this tile. */
  multiplier: number;
  /** Relative chance of this tile: a weight of 2 comes up twice as often as a weight of 1. */
  weight: number;
}

export interface SlideRound {
  /** Round number, starting at 1. */
  id: number;
  /** Multiplier the strip stopped on. */
  multiplier: number;
  /** Amount bet. */
  bet: number;
  /** Amount paid back. */
  payout: number;
}

export interface SlideGameProps {
  /** Controlled play-money balance. */
  balance?: number;
  /** Starting balance when uncontrolled; the reset button returns to it. */
  defaultBalance?: number;
  /** Called with the new balance after a bet, a payout or a reset. */
  onBalanceChange?: (balance: number) => void;
  /** Bet amount shown at first. */
  defaultBet?: number;
  /** Smallest bet. */
  minBet?: number;
  /** The kinds of tile on the strip and how often each comes up. */
  tiles?: SlideTile[];
  /** Seconds the strip takes to slide and slow down to its result. */
  duration?: number;
  /** Called when the strip has stopped, with the result. */
  onRoundEnd?: (round: SlideRound) => void;
  /** Random source returning a number in [0, 1). Called only after a bet, to pick the result and fill the strip. */
  random?: () => number;
  /** Name shown in the header. */
  title?: string;
  /** Extra class for the card. */
  className?: string;
}

type Phase = "idle" | "sliding" | "landed";
interface Cell { id: number; multiplier: number }
interface Spin { id: number; from: number; target: number; nudge: number; bet: number; multiplier: number }

/** Default tiles. Weights add up to 100, so each weight is its chance in percent; the average payout is 0.97 of the bet. */
const defaultTiles: SlideTile[] = [
  { multiplier: 0, weight: 32 },
  { multiplier: 0.5, weight: 24 },
  { multiplier: 1.2, weight: 20 },
  { multiplier: 1.5, weight: 10 },
  { multiplier: 2, weight: 7 },
  { multiplier: 3, weight: 4 },
  { multiplier: 5, weight: 2 },
  { multiplier: 10, weight: 1 },
];

// Strip geometry in px; the CSS reads the same numbers through custom properties.
const tileWidth = 76, tileGap = 8, pitch = tileWidth + tileGap;
/** Tiles kept on each side of the center, enough to fill the widest card. */
const lead = 8;
/** Tiles that pass under the marker in one slide. */
const travel = 36;
/** Leaves at speed and spends most of its time slowing down. */
const slowdown = [0.09, 0.62, 0.1, 1] as const;

const offsetFor = (index: number) => -(index * pitch + tileWidth / 2);
const label = (multiplier: number) => `${multiplier}×`;
const tierOf = (multiplier: number) => (multiplier >= 5 ? "top" : multiplier >= 2 ? "good" : multiplier >= 1 ? "base" : multiplier > 0 ? "low" : "zero");
const toneOf = (multiplier: number): HistoryEntry["tone"] => (multiplier >= 5 ? "high" : multiplier >= 1 ? "mid" : "low");

/** A slide game with fake money: a strip of multiplier tiles shoots past a center marker, slows down and stops on the multiplier that pays the bet. */
export function SlideGame({
  balance,
  defaultBalance = 1000,
  onBalanceChange,
  defaultBet = 10,
  minBet = 1,
  tiles = defaultTiles,
  duration = 3.8,
  onRoundEnd,
  random = Math.random,
  title = "Slide",
  className,
}: SlideGameProps) {
  const reduceMotion = useReducedMotion();
  const money = usePlayMoney({ balance, defaultBalance, onBalanceChange });
  const kinds = useMemo(() => { const valid = tiles.filter(tile => tile.weight > 0 && tile.multiplier >= 0); return valid.length ? valid : defaultTiles; }, [tiles]);
  const totalWeight = useMemo(() => kinds.reduce((sum, tile) => sum + tile.weight, 0), [kinds]);
  const [bet, setBet] = useState(defaultBet);
  const [phase, setPhase] = useState<Phase>("idle");
  // The strip on first paint is a fixed pattern: nothing random happens before the first bet.
  const [strip, setStrip] = useState<Cell[]>(() => Array.from({ length: lead * 2 + 1 }, (_, index) => ({ id: index, multiplier: kinds[(index * 5 + 2) % kinds.length]?.multiplier ?? 0 })));
  const [spin, setSpin] = useState<Spin | null>(null);
  const [history, setHistory] = useState<{ id: number; multiplier: number }[]>([]);
  const [announcement, setAnnouncement] = useState("");

  const x = useMotionValue(offsetFor(lead));
  const fade = useMotionValue(1);
  const centered = useRef(lead);
  const cellId = useRef(lead * 2 + 1);
  const pointer = useRef<HTMLSpanElement>(null);

  const land = (round: Spin) => {
    const payout = roundAmount(round.bet * round.multiplier);
    money.pay(payout);
    setPhase("landed");
    setHistory(list => [{ id: round.id, multiplier: round.multiplier }, ...list].slice(0, 8));
    setAnnouncement(`Landed on ${round.multiplier} times. ${payout > 0 ? `${formatAmount(payout)} back.` : "Nothing back this time."}`);
    onRoundEnd?.({ id: round.id, multiplier: round.multiplier, bet: round.bet, payout });
  };
  const landRef = useRef(land);
  useEffect(() => { landRef.current = land; });

  // Runs one slide. The new strip starts with the tiles that were on screen, so the jump back to its start is invisible.
  useLayoutEffect(() => {
    if (!spin) return;
    let cancelled = false;
    let settle: ReturnType<typeof animate> | undefined;
    x.jump(offsetFor(spin.from));
    if (reduceMotion) {
      // No travel: the strip is swapped for its final position with a short fade.
      x.jump(offsetFor(spin.target));
      fade.jump(0);
      const appear = animate(fade, 1, { duration: motionTokens.duration.standard });
      appear.then(() => { if (!cancelled) landRef.current(spin); });
      return () => { cancelled = true; appear.stop(); fade.jump(1); };
    }
    // It stops a little off center, like a real strip, then eases onto the tile.
    const slide = animate(x, offsetFor(spin.target) + spin.nudge, { duration, ease: [...slowdown] });
    slide.then(() => {
      if (cancelled) return;
      landRef.current(spin);
      settle = animate(x, offsetFor(spin.target), motionTokens.spring.gentle);
    });
    return () => { cancelled = true; slide.stop(); settle?.stop(); };
  }, [spin, duration, reduceMotion, x, fade]);

  // The pointer flicks each time a tile edge passes under it.
  useEffect(() => {
    if (reduceMotion) return;
    let last = Math.round((-x.get() - tileWidth / 2) / pitch), flickedAt = 0;
    return x.on("change", value => {
      const index = Math.round((-value - tileWidth / 2) / pitch);
      if (index === last) return;
      last = index;
      const now = performance.now();
      if (now - flickedAt < 60 || !pointer.current) return;
      flickedAt = now;
      animate(pointer.current, { rotate: [-20, 0] }, { duration: 0.18, ease: "easeOut" });
    });
  }, [x, reduceMotion]);

  const play = () => {
    if (phase === "sliding" || bet < minBet || !money.spend(bet)) return;
    const chance = () => Math.min(Math.max(random(), 0), 0.999999);
    const draw = () => {
      let mark = chance() * totalWeight;
      for (const tile of kinds) { mark -= tile.weight; if (mark < 0) return tile.multiplier; }
      return kinds[kinds.length - 1]?.multiplier ?? 0;
    };
    const cell = (multiplier: number): Cell => ({ id: cellId.current++, multiplier });
    const result = draw();
    const kept = strip.slice(centered.current - lead, centered.current + lead + 1);
    const target = lead + travel;
    const next = [...kept, ...Array.from({ length: target - kept.length }, () => cell(draw())), cell(result), ...Array.from({ length: lead }, () => cell(draw()))];
    centered.current = target;
    setStrip(next);
    setSpin(current => ({ id: (current?.id ?? 0) + 1, from: lead, target, nudge: (chance() - 0.5) * tileWidth * 0.72, bet, multiplier: result }));
    setPhase("sliding");
    setAnnouncement(`Sliding with a bet of ${formatAmount(bet)}.`);
  };

  const sliding = phase === "sliding";
  const broke = !sliding && money.balance < minBet;
  const entries = useMemo<HistoryEntry[]>(() => history.map(item => ({ id: item.id, label: label(item.multiplier), tone: toneOf(item.multiplier) })), [history]);
  const payout = spin ? roundAmount(spin.bet * spin.multiplier) : 0;
  const status = phase === "landed" && spin
    ? { key: `landed-${spin.id}`, tone: spin.multiplier >= 1 ? "success" : "muted", text: `Landed on ${label(spin.multiplier)} · ${payout > 0 ? `${formatAmount(payout)} back` : "nothing back this time"}` }
    : sliding
      ? { key: "sliding", tone: "muted", text: "Sliding…" }
      : { key: "idle", tone: "muted", text: "Bet to send the strip sliding" };

  return (
    <GameFrame title={title} money={money} busy={sliding} announcement={announcement} className={[styles.root, className].filter(Boolean).join(" ")}>
      <div className={styles.historyRow}>
        <span className={styles.historyLabel}>Last results</span>
        {entries.length ? <HistoryChips entries={entries} label="Multipliers of the last rounds, newest first" /> : <span className={styles.empty}>none yet</span>}
      </div>
      <div className={styles.stage} data-phase={phase} style={{ "--tile": `${tileWidth}px`, "--tile-gap": `${tileGap}px` } as CSSProperties}>
        <div className={styles.viewport} aria-hidden="true">
          <motion.div className={styles.strip} style={{ x, opacity: fade }}>
            {strip.map((cell, index) => (
              <div
                key={cell.id}
                className={styles.tile}
                data-tier={tierOf(cell.multiplier)}
                data-winner={(phase === "landed" && index === spin?.target) || undefined}
                // Only the tiles of the first strip stagger in, outward from the center; later tiles mount off screen.
                style={cell.id <= lead * 2 ? { animationDelay: `${Math.abs(cell.id - lead) * 45}ms` } : undefined}
              >
                {label(cell.multiplier)}
              </div>
            ))}
          </motion.div>
        </div>
        <span className={styles.marker} aria-hidden="true"><span ref={pointer} className={styles.pointer} /></span>
        <p className={styles.result}>
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span
              key={status.key}
              className={styles.resultText}
              data-tone={status.tone}
              initial={{ opacity: 0, y: reduceMotion ? 0 : 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, transition: { duration: motionTokens.duration.instant } }}
              transition={motionTokens.spring.snappy}
            >
              {status.text}
            </motion.span>
          </AnimatePresence>
        </p>
      </div>
      <ul className={styles.chances} aria-label="Chance of each multiplier">
        {kinds.map(tile => {
          const share = (tile.weight / totalWeight) * 100;
          return <li key={tile.multiplier} className={styles.chance} data-tier={tierOf(tile.multiplier)}><b>{label(tile.multiplier)}</b>{share >= 10 ? Math.round(share) : Math.round(share * 10) / 10}%</li>;
        })}
      </ul>
      <div className={styles.controls}>
        <BetField value={bet} onValueChange={setBet} min={minBet} max={money.balance} disabled={sliding} />
        {broke ? (
          <PlayButton labelKey="refill" tone="neutral" onClick={money.reset}>Reset the balance</PlayButton>
        ) : sliding ? (
          <PlayButton labelKey="sliding" tone="neutral" disabled onClick={() => undefined}>Sliding…</PlayButton>
        ) : bet > money.balance ? (
          <PlayButton labelKey="lower" tone="neutral" onClick={() => setBet(money.balance)}>Lower the bet to {formatAmount(money.balance)}</PlayButton>
        ) : (
          <PlayButton labelKey="bet" onClick={play}>{phase === "landed" ? "Bet again" : "Bet"}</PlayButton>
        )}
      </div>
    </GameFrame>
  );
}

export default SlideGame;

.root { max-width: 36rem; }

.historyRow { display: flex; min-width: 0; min-height: 1.75rem; align-items: center; gap: var(--space-3); margin: var(--space-3) var(--space-4) 0; }
.historyLabel { flex: none; color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; white-space: nowrap; }
.empty { color: var(--text-muted); font-size: var(--text-xs); }

.stage { position: relative; margin: var(--space-3) var(--space-4) 0; border: 1px solid var(--border-subtle); border-radius: var(--radius-control); background: var(--background); }
/* The strip runs off both sides; it fades at the edges of its window (a scroller edge fade, not decoration). */
.viewport { position: relative; height: calc(var(--tile) + var(--space-10)); overflow: hidden; border-radius: inherit; -webkit-mask-image: linear-gradient(to right, transparent, #000 2.75rem, #000 calc(100% - 2.75rem), transparent); mask-image: linear-gradient(to right, transparent, #000 2.75rem, #000 calc(100% - 2.75rem), transparent); }
.strip { position: absolute; top: var(--space-5); left: 50%; display: flex; gap: var(--tile-gap); will-change: transform; }

.tile { display: grid; width: var(--tile); height: var(--tile); flex: none; place-items: center; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); color: var(--text-secondary); font-family: var(--font-display); font-size: var(--text-xl); font-weight: 600; font-variant-numeric: tabular-nums; letter-spacing: var(--tracking-display); animation: tileIn var(--duration-spring) var(--ease-spring) both; transition: scale var(--duration-spring) var(--ease-spring), opacity var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
/* Tiers, from nothing back to the rare top tiles. */
.tile[data-tier="zero"] { border-style: dashed; background: transparent; color: var(--text-muted); }
.tile[data-tier="base"] { border-color: color-mix(in oklab, var(--tone-sky) 30%, var(--border)); background: color-mix(in oklab, var(--tone-sky) 14%, var(--surface)); color: var(--tone-sky); }
.tile[data-tier="good"] { border-color: color-mix(in oklab, var(--tone-violet) 34%, var(--border)); background: color-mix(in oklab, var(--tone-violet) 16%, var(--surface)); color: var(--tone-violet); }
.tile[data-tier="top"] { border-color: transparent; background: var(--accent); color: var(--accent-foreground); }
/* After the stop the winner steps forward and the rest step back. */
.stage[data-phase="landed"] .tile:not([data-winner]) { opacity: .4; }
.tile[data-winner] { scale: 1.1; box-shadow: var(--shadow-raised); }

/* The marker: a frame the size of one tile in the middle of the window, with a pointer hinged on its top edge. */
.marker { position: absolute; top: calc(var(--space-5) - 5px); left: 50%; width: calc(var(--tile) + 10px); height: calc(var(--tile) + 10px); margin-left: calc((var(--tile) + 10px) / -2); border: 2px solid var(--accent-strong); border-radius: calc(var(--radius-control) + 5px); pointer-events: none; transition: scale var(--duration-spring) var(--ease-spring); }
.stage[data-phase="landed"] .marker { scale: 1.1; }
.pointer { position: absolute; top: -9px; left: 50%; width: 14px; height: 11px; margin-left: -7px; background: var(--accent-strong); clip-path: polygon(0 0, 100% 0, 50% 100%); transform-origin: 50% 0; }

.result { position: relative; display: grid; min-height: 2.5rem; margin: 0; place-items: center; border-top: 1px solid var(--border-subtle); padding: var(--space-2) var(--space-3); text-align: center; }
.resultText { color: var(--text-muted); font-size: var(--text-sm); font-weight: 500; font-variant-numeric: tabular-nums; }
.resultText[data-tone="success"] { color: var(--success); }

.chances { display: flex; flex-wrap: wrap; gap: var(--space-1) var(--space-2); margin: var(--space-3) var(--space-4) 0; padding: 0; list-style: none; }
.chance { display: inline-flex; align-items: center; gap: var(--space-1); border-radius: var(--radius-pill); padding: 2px var(--space-2); background: var(--surface-muted); color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; white-space: nowrap; }
.chance b { color: var(--text-secondary); font-weight: 600; }
.chance[data-tier="base"] b { color: var(--tone-sky); }
.chance[data-tier="good"] b { color: var(--tone-violet); }
.chance[data-tier="top"] b { color: var(--accent-strong); }

.controls { display: grid; gap: var(--space-3); padding: var(--space-4); }
@container (min-width: 28rem) { .controls { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); align-items: end; } }

@keyframes tileIn { from { opacity: 0; transform: translateY(10px) scale(.9); } }
@media (prefers-reduced-motion: reduce) {
  .tile, .marker { transition: none; }
  .tile { animation: none; }
  .tile[data-winner], .stage[data-phase="landed"] .marker { scale: none; }
}

"use client";

/**
 * Shared parts of the play-money toy games: a fake balance, the bet field, the action button, the result chips and the card frame.
 * Each game ships its own copy of this file, so a game installs on its own.
 */
import { useCallback, useEffect, useId, useRef, useState } from "react";
import type { ReactNode } from "react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { Coins, RotateCcw } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./play-money.module.css";

const amountFormat = new Intl.NumberFormat("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/** 1234.5 → "1,234.50". Play money has no currency sign on purpose. */
export const formatAmount = (value: number) => amountFormat.format(value);
/** 2.5 → "2.50×", 12.34 → "12.3×", 120 → "120×". */
export const formatMultiplier = (value: number) => `${value >= 100 ? value.toFixed(0) : value >= 10 ? value.toFixed(1) : value.toFixed(2)}×`;
/** Keeps amounts at two decimals, so sums never drift. */
export const roundAmount = (value: number) => Math.round(value * 100) / 100;

export interface PlayMoneyOptions {
  /** Controlled balance. */
  balance?: number;
  /** Starting balance when uncontrolled; a reset returns to it. */
  defaultBalance: number;
  /** Called with the new balance after a bet, a payout or a reset. */
  onBalanceChange?: (balance: number) => void;
}

export interface PlayMoneyGain {
  /** Changes on every payout, so the same amount twice still animates. */
  id: number;
  /** Amount paid. */
  amount: number;
}

export interface PlayMoney {
  /** Current fake balance. */
  balance: number;
  /** The latest payout, for the "+12.40" flyer next to the balance. */
  gain: PlayMoneyGain | null;
  /** Takes a bet out of the balance. Returns false (and takes nothing) when the balance is too low. */
  spend: (amount: number) => boolean;
  /** Adds a payout to the balance. */
  pay: (amount: number) => void;
  /** Returns the balance to its starting amount. */
  reset: () => void;
}

/** A fake balance, controlled or uncontrolled. Reads go through a ref, so a bet and a payout in the same tick both count. */
export function usePlayMoney({ balance: controlled, defaultBalance, onBalanceChange }: PlayMoneyOptions): PlayMoney {
  const [internal, setInternal] = useState(defaultBalance);
  const [gain, setGain] = useState<PlayMoneyGain | null>(null);
  const balance = controlled ?? internal;
  const latest = useRef(balance);
  const gainId = useRef(0);
  useEffect(() => { latest.current = balance; }, [balance]);

  const commit = useCallback((next: number) => {
    const value = roundAmount(Math.max(0, next));
    latest.current = value;
    setInternal(value);
    onBalanceChange?.(value);
  }, [onBalanceChange]);

  const spend = useCallback((amount: number) => {
    if (!(amount > 0) || amount > latest.current + 1e-9) return false;
    commit(latest.current - amount);
    return true;
  }, [commit]);

  const pay = useCallback((amount: number) => {
    if (!(amount > 0)) return;
    commit(latest.current + amount);
    gainId.current += 1;
    setGain({ id: gainId.current, amount: roundAmount(amount) });
  }, [commit]);

  const reset = useCallback(() => { setGain(null); commit(defaultBalance); }, [commit, defaultBalance]);

  return { balance, gain, spend, pay, reset };
}

function Balance({ value, gain }: { value: number; gain: PlayMoneyGain | null }) {
  const reduceMotion = useReducedMotion();
  const shown = useMotionValue(value);
  const text = useTransform(shown, formatAmount);
  useEffect(() => {
    if (reduceMotion) { shown.set(value); return; }
    const controls = animate(shown, value, { duration: motionTokens.duration.considered, ease: [...motionTokens.ease.standard] });
    return () => controls.stop();
  }, [value, reduceMotion, shown]);
  return (
    <span className={styles.balance}>
      <Coins size={15} aria-hidden="true" />
      <span className={styles.srOnly}>Play-money balance: {formatAmount(value)}</span>
      <motion.span className={styles.balanceValue} aria-hidden="true">{text}</motion.span>
      <AnimatePresence>
        {gain ? (
          <motion.span
            key={gain.id}
            className={styles.gain}
            aria-hidden="true"
            initial={{ opacity: 0, y: reduceMotion ? -14 : 0 }}
            animate={{ opacity: [0, 1, 1, 0], y: reduceMotion ? -14 : -18 }}
            transition={{ duration: 1.4, times: [0, 0.12, 0.7, 1], ease: "easeOut" }}
          >
            +{formatAmount(gain.amount)}
          </motion.span>
        ) : null}
      </AnimatePresence>
    </span>
  );
}

export interface GameFrameProps {
  /** Name of the game, shown in the header and used as the region label. */
  title: string;
  /** The balance from `usePlayMoney`. */
  money: PlayMoney;
  /** True while a round is running: the reset button waits for it to end. */
  busy?: boolean;
  /** Result text for screen readers, announced politely. */
  announcement?: string;
  /** Extra class for the card. */
  className?: string;
  /** The stage and controls of the game. */
  children: ReactNode;
}

/** The card around a game: title, a "Play money" tag, the balance and its reset. */
export function GameFrame({ title, money, busy = false, announcement = "", className, children }: GameFrameProps) {
  return (
    <section className={[styles.frame, className].filter(Boolean).join(" ")} aria-label={title}>
      <header className={styles.header}>
        <div className={styles.heading}>
          <span className={styles.title}>{title}</span>
          <span className={styles.tag}>Play money</span>
        </div>
        <div className={styles.wallet}>
          <Balance value={money.balance} gain={money.gain} />
          <button type="button" className={styles.reset} onClick={money.reset} disabled={busy} aria-label="Reset balance" title="Reset balance">
            <RotateCcw size={15} aria-hidden="true" />
          </button>
        </div>
      </header>
      {children}
      <p className={styles.srOnly} role="status" aria-live="polite">{announcement}</p>
    </section>
  );
}

export interface BetFieldProps {
  /** Bet amount. */
  value: number;
  /** Called with the new amount, already clamped between `min` and `max`. */
  onValueChange: (value: number) => void;
  /** Smallest bet. */
  min?: number;
  /** Largest bet, usually the balance. */
  max: number;
  /** Locks the field, for example while a round runs. */
  disabled?: boolean;
  /** Field label. */
  label?: string;
}

/** Keeps digits and one dot, two decimals at most. */
const cleanAmount = (text: string) => {
  const [whole = "", ...rest] = text.replace(/[^\d.]/g, "").split(".");
  return rest.length ? `${whole}.${rest.join("").slice(0, 2)}` : whole;
};

/** Bet amount with half, double and max shortcuts. Typing is free; the amount is clamped when the field loses focus. */
export function BetField({ value, onValueChange, min = 1, max, disabled = false, label = "Bet" }: BetFieldProps) {
  const id = useId();
  const [draft, setDraft] = useState<string | null>(null);
  const clamp = (amount: number) => roundAmount(Math.min(Math.max(amount, min), Math.max(min, max)));
  const set = (amount: number) => { setDraft(null); onValueChange(clamp(amount)); };
  return (
    <div className={styles.field}>
      <label className={styles.fieldLabel} htmlFor={id}>{label}</label>
      <div className={styles.fieldBox} data-disabled={disabled || undefined}>
        <input
          id={id}
          className={styles.fieldInput}
          type="text"
          inputMode="decimal"
          autoComplete="off"
          disabled={disabled}
          value={draft ?? formatAmount(value)}
          onFocus={event => event.currentTarget.select()}
          onChange={event => {
            const text = cleanAmount(event.target.value);
            setDraft(text);
            const amount = Number.parseFloat(text);
            if (Number.isFinite(amount) && amount >= min) onValueChange(roundAmount(Math.min(amount, Math.max(min, max))));
          }}
          onBlur={() => { const amount = Number.parseFloat(draft ?? ""); set(Number.isFinite(amount) ? amount : value); }}
          onKeyDown={event => { if (event.key === "Enter") event.currentTarget.blur(); }}
        />
        <div className={styles.quick} role="group" aria-label={`Adjust ${label.toLowerCase()}`}>
          <button type="button" className={styles.quickButton} disabled={disabled} onClick={() => set(value / 2)} aria-label="Halve the bet">½</button>
          <button type="button" className={styles.quickButton} disabled={disabled} onClick={() => set(value * 2)} aria-label="Double the bet">2×</button>
          <button type="button" className={styles.quickButton} disabled={disabled} onClick={() => set(max)} aria-label="Bet the whole balance">Max</button>
        </div>
      </div>
    </div>
  );
}

export interface AmountFieldProps {
  /** Field label. */
  label: string;
  /** Text in the field (digits and one dot). Empty means "not set". */
  value: string;
  /** Called with the cleaned text on every edit. */
  onValueChange: (value: string) => void;
  /** Shown while the field is empty. */
  placeholder?: string;
  /** Short unit after the number, for example "×". */
  suffix?: string;
  /** Locks the field. */
  disabled?: boolean;
}

/** A small optional number, such as a target multiplier. */
export function AmountField({ label, value, onValueChange, placeholder, suffix, disabled = false }: AmountFieldProps) {
  const id = useId();
  return (
    <div className={styles.field}>
      <label className={styles.fieldLabel} htmlFor={id}>{label}</label>
      <div className={styles.fieldBox} data-disabled={disabled || undefined}>
        <input id={id} className={styles.fieldInput} type="text" inputMode="decimal" autoComplete="off" disabled={disabled} placeholder={placeholder} value={value} onChange={event => onValueChange(cleanAmount(event.target.value))} />
        {suffix ? <span className={styles.suffix} aria-hidden="true">{suffix}</span> : null}
      </div>
    </div>
  );
}

export interface FieldGroupProps {
  /** Label above the control. */
  label: string;
  /** The control: a stepper, a segmented choice… */
  children: ReactNode;
}

/** A labelled slot for a custom control, aligned with the bet field. */
export function FieldGroup({ label, children }: FieldGroupProps) {
  const id = useId();
  return (
    <div className={styles.field} role="group" aria-labelledby={id}>
      <span className={styles.fieldLabel} id={id}>{label}</span>
      {children}
    </div>
  );
}

export interface PlayButtonProps {
  /** Identifies the label: when it changes, the old label slides out and the new one slides in. */
  labelKey: string;
  /** "accent" for the main action, "neutral" for a waiting state. */
  tone?: "accent" | "neutral";
  /** Turns the action off. The button stays focusable (aria-disabled), so keyboard focus is never lost while a round runs. */
  disabled?: boolean;
  /** Runs the action. */
  onClick: () => void;
  /** Label content. */
  children: ReactNode;
}

/** The main action of a game. One button keeps focus while its label changes (Bet, Cash out, …). */
export function PlayButton({ labelKey, tone = "accent", disabled = false, onClick, children }: PlayButtonProps) {
  const reduceMotion = useReducedMotion();
  const shift = reduceMotion ? 0 : 10;
  return (
    <motion.button
      type="button"
      className={styles.play}
      data-tone={tone}
      aria-disabled={disabled || undefined}
      onClick={() => { if (!disabled) onClick(); }}
      whileTap={disabled || reduceMotion ? undefined : { scale: 0.97 }}
      transition={motionTokens.spring.snappy}
    >
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.span
          key={labelKey}
          className={styles.playLabel}
          initial={{ opacity: 0, y: shift }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -shift, transition: { duration: motionTokens.duration.instant } }}
          transition={motionTokens.spring.snappy}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </motion.button>
  );
}

export interface HistoryEntry {
  /** Stable key of the round. */
  id: number | string;
  /** Text of the chip, for example "2.31×". */
  label: string;
  /** "low" is muted, "mid" is tinted, "high" takes the accent fill. */
  tone: "low" | "mid" | "high";
}

export interface HistoryChipsProps {
  /** Past results, newest first. */
  entries: HistoryEntry[];
  /** Label of the list for screen readers. */
  label: string;
}

/** A row of past results. A new chip springs in at the start and pushes the others along. */
export function HistoryChips({ entries, label }: HistoryChipsProps) {
  const reduceMotion = useReducedMotion();
  const mounted = useRef(false);
  useEffect(() => { mounted.current = true; }, []);
  return (
    <ol className={styles.history} aria-label={label}>
      <AnimatePresence mode="popLayout">
        {entries.map((entry, index) => (
          <motion.li
            key={entry.id}
            layout={reduceMotion ? false : "position"}
            className={styles.chip}
            data-tone={entry.tone}
            initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6, x: -14 }}
            animate={{ opacity: 1, scale: 1, x: 0 }}
            exit={{ opacity: 0, transition: { duration: motionTokens.duration.instant } }}
            transition={{ ...motionTokens.spring.snappy, delay: mounted.current ? 0 : index * motionTokens.stagger.item }}
          >
            {entry.label}
          </motion.li>
        ))}
      </AnimatePresence>
    </ol>
  );
}

